        $switch($local,true);DB::table('settings')->where('name','app_balance')->update(['payload'=>'"0"']);$journal=app(\App\Services\Dashboard\DesktopDashboardJournal::class);$command=(string)\Illuminate\Support\Str::uuid();
        $form=fn()=>$make('updateSetting',$command,['logo'=>$uploaded($png,'offline.png')]);$response=app(\App\Http\Middleware\DesktopDashboardJournal::class)->handle($form(),$original);$envelope=$journal->pending($device)[0];$path=$envelope['local_result']['after']['logo']['value'];
